arguments.command:
curl -s -X POST https://slack.com/api/users.list -H 'Authorization: Bearer <TOKEN>' -d 'limit=1000' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR',d); sys.exit()
for u in d['members']:
    if u.get('deleted'): continue
    name=u.get('real_name') or u.get('profile',{}).get('real_name','')
    if 'omar' in name.lower():
        print(u['id'], '|', name, '|', u.get('profile',{}).get('display_name',''), '|', u.get('profile',{}).get('email',''))
"

